selector:
@import url("../datasheet-system.css");
@import url("../unit-art.css");

/* V1's palette belongs to datasheets and datasheet details. The surrounding
   V2 application keeps its existing navigation and generic-card palette. */
:where(.unit-card.surface, .v2-detail-dialog:has(.unit-card), .v2-detail-dialog:has(.popup-weapon-profile), .v2-related-dialog)

declarations:
color-scheme: dark;
  --ds-ui: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
  --ds-data: "SFMono-Regular", Consolas, "Liberation Mono", monospace;
  --header: 70px;
  --bg: var(--book-bg, #0d0f0d);
  --underhive: var(--book-canvas, #121512);
  --panel: var(--book-panel, #191f1a);
  --panel-2: var(--book-panel-raised, #252c25);
  --ink: var(--book-ink, #e2dcc9);
  --muted: var(--book-muted, #969589);
  --green: var(--book-accent, #bfd58c);
  --green-deep: var(--book-accent-deep, #7d9257);
  --bronze: var(--book-metal, #8d7448);
  --bronze-bright: var(--book-metal-bright, #c7ae75);
  --pink: var(--book-signal, #d5488e);
  --pink-deep: var(--book-signal-deep, #74143f);
  --faction-gradient: linear-gradient(90deg, var(--book-accent, #c8df7f) 0 72%, var(--book-accent, #c8df7f) 74%, var(--book-signal, #c3167c) 82%, var(--book-signal, #c3167c) 100%);
  --line: rgba(var(--book-ink-rgb, 216, 209, 191), .14);
  --soft-line: rgba(var(--book-ink-rgb, 216, 209, 191), .08);
  /* Composite V1's translucent surface over its original dark substrate,
     independently of the accepted V2 application background. */
  --glass: color-mix(in srgb, rgb(var(--book-panel-rgb, 26, 30, 27)) 94%, var(--bg));
  --shadow: 0 26px 58px rgba(0, 0, 0, .46), 0 0 0 1px rgba(0, 0, 0, .48);
  --radius: 2px;
  --body-size: 17px;
  --data-size: 14px;

selector:
/* Native V2 detail dialogs use the V1 full-entry surface when their content
   is a datasheet. Other V2 detail cards keep the generic light treatment. */
.v2-detail-dialog:has(:is(.unit-card, .popup-weapon-profile))

declarations:
width: min(1120px, calc(100vw - 48px));
  max-width: min(1120px, calc(100vw - 48px));
  max-height: calc(100dvh - 64px);
  overflow: hidden;
  border: 0;
  border-top: 4px solid var(--green-deep);
  border-radius: 0;
  color: var(--ink);
  background:
    radial-gradient(circle at 100% 0, rgba(var(--book-signal-rgb, 213, 72, 142), .12), transparent 320px),
    radial-gradient(circle at 0 100%, rgba(var(--book-accent-deep-rgb, 125, 146, 87), .12), transparent 360px),
    var(--panel);
  box-shadow: 0 40px 120px rgba(0,0,0,.88), 0 0 0 1px rgba(var(--book-metal-bright-rgb, 199, 174, 117), .36);

border-bottom: 1px solid var(--line);
  background: rgba(var(--book-void-rgb, 10, 14, 11), .86);
  color: var(--ink);

width: 100%;
    height: 100%;
    max-width: none;
    max-height: none;
    margin: 0;
    border: 0;
